<?php require_once __DIR__.'/config.php'; if($_SERVER['REQUEST_METHOD']==='POST'){ $email=strtolower(trim($_POST['email']??'')); $s=db()->prepare('SELECT * FROM users WHERE email=?');$s->execute([$email]);$u=$s->fetch(); if($u){$token=bin2hex(random_bytes(24));db()->prepare('UPDATE users SET reset_token_hash=?,reset_expires_at=DATE_ADD(NOW(),INTERVAL 30 MINUTE) WHERE id=?')->execute([hash('sha256',$token),$u['id']]);send_verification_email($email,$u['name'],$token);} flash('success','หากอีเมลนี้มีอยู่ในระบบ จะได้รับรหัสสำหรับรีเซ็ตรหัสผ่าน');redirect('reset.php?email='.urlencode($email));}$page_title='ลืมรหัสผ่าน | '.STORE_NAME;require __DIR__.'/partials_header.php'; ?><main class="auth-wrap"><form class="auth-card" method="post"><h1>ลืมรหัสผ่าน</h1><p>กรอกอีเมลเพื่อขอรหัสรีเซ็ตรหัสผ่าน</p><div class="field"><label>อีเมล</label><input type="email" name="email" required autofocus></div><button class="button full">ขอรหัสรีเซ็ต →</button><p class="fine"><a href="login.php">กลับเข้าสู่ระบบ</a></p></form></main><?php require __DIR__.'/partials_footer.php'; ?>
